const q = $('Data Webhook').first().json.query || {};
const type = String(q.type || 'bootstrap');
const rows = (n) => $(n).all().map(i => i.json).filter(j => j && j.id !== undefined);
const leads = rows('Load Leads');
const services = rows('Load Services');
const connectors = rows('Load Connectors');
const settingsRows = rows('Load Settings');
const runs = rows('Load Runs');
const settings = {};
for (const s of settingsRows) settings[s.setting_key] = s.setting_value;
const sortedRuns = runs.slice().sort((a, b) => String(b.started_at_iso || '').localeCompare(String(a.started_at_iso || '')));
const stats = () => {
  const byStatus = {};
  let sum = 0;
  let n = 0;
  let pending = 0;
  for (const l of leads) {
    byStatus[l.status || 'New'] = (byStatus[l.status || 'New'] || 0) + 1;
    if (l.status !== 'Rejected' && l.status !== 'Duplicate') { sum += Number(l.lead_score) || 0; n++; }
    if (l.human_review_status === 'Pending review' || l.human_review_status === 'Edited') pending++;
  }
  return { total: leads.length, by_status: byStatus, avg_score: n ? Math.round(sum / n) : 0, pending_reviews: pending, runs_total: runs.length };
};
let code = 200;
let body;
if (type === 'leads') {
  let list = leads;
  if (q.status) list = list.filter(l => String(l.status) === String(q.status));
  if (q.min_score) list = list.filter(l => (Number(l.lead_score) || 0) >= Number(q.min_score));
  if (q.review) list = list.filter(l => l.human_review_status === 'Pending review' || l.human_review_status === 'Edited');
  if (q.search) {
    const s = String(q.search).toLowerCase();
    list = list.filter(l => [l.company, l.person_name, l.requirement, l.original_post, l.matched_service, l.lead_id].join(' ').toLowerCase().includes(s));
  }
  list = list.slice().sort((a, b) => ((Number(b.lead_score) || 0) - (Number(a.lead_score) || 0)) || String(b.last_updated || '').localeCompare(String(a.last_updated || '')));
  const lim = Number(q.limit) > 0 ? Number(q.limit) : 200;
  body = { leads: list.slice(0, lim), total: list.length };
} else if (type === 'lead') {
  const l = leads.find(x => String(x.lead_id) === String(q.lead_id || ''));
  if (l) body = { lead: l }; else { code = 404; body = { error: 'Lead not found' }; }
} else if (type === 'services') {
  body = { services: services };
} else if (type === 'connectors') {
  body = { connectors: connectors };
} else if (type === 'settings') {
  body = { settings: settings };
} else if (type === 'runs') {
  if (q.run_id) {
    const r = runs.find(x => String(x.run_id) === String(q.run_id));
    if (r) body = { run: r }; else { code = 404; body = { error: 'Run not found' }; }
  } else body = { runs: sortedRuns.slice(0, 20) };
} else if (type === 'stats') {
  body = stats();
} else if (type === 'bootstrap') {
  body = { stats: stats(), services: services, connectors: connectors, settings: settings, runs: sortedRuns.slice(0, 20) };
} else {
  code = 400;
  body = { error: 'Unknown type. Use leads, lead, services, connectors, settings, runs, stats or bootstrap.' };
}
return [{ json: { code: code, body: body } }];

const b = $('Action Webhook').first().json.body || {};
const action = String(b.action || '');
const lead = $input.all().map(i => i.json).find(j => j && j.lead_id) || null;
const nowIso = $now.setZone('Asia/Calcutta').toISO();
const fail = (code, error) => [{ json: { valid: false, code: code, error: error, action: action } }];
const base = { valid: true, action: action, now_iso: nowIso, lead_id: String(b.lead_id || ''), feedback_decision: '', feedback_reason: String(b.reason || ''), previous_intent: lead ? String(lead.intent || '') : '' };
const needLead = ['update_lead', 'outreach_action', 'outreach_generate'];
if (needLead.includes(action)) {
  if (!b.lead_id) return fail(400, 'lead_id is required');
  if (!lead) return fail(404, 'Lead not found');
}
if (action === 'manual') {
  const raw = String(b.raw_input || '').trim();
  if (!raw) return fail(400, 'raw_input is required');
  const m = raw.match(/https?:\/\/[^\s"'<>]+/i);
  return [{ json: Object.assign(base, {
    raw_input: raw,
    candidate_url: m ? m[0].replace(/[).,]+$/, '') : '',
    instruction_context: String(b.instruction || '').trim() || 'Determine whether this is a genuine potential client who needs one of our services. Exclude service providers, agencies, freelancers, job seekers and employers hiring staff.',
    generate_outreach: b.generate_outreach === true || b.generate_outreach === 'true',
  }) }];
}
if (action === 'research') {
  const list = Array.isArray(b.leads) ? b.leads.filter(l => l && l.lead_id) : [];
  if (!list.length) return fail(400, 'leads (array of {lead_id, original_post, source_url, source}) is required');
  return [{ json: Object.assign(base, { leads: list.slice(0, 25), instruction_context: String(b.instruction || '').trim() || 'Re-research this lead. Determine whether it is a genuine potential client who needs one of our services. Exclude service providers, agencies, freelancers, job seekers and employers hiring staff.' }) }];
}
if (action === 'update_lead') {
  const newStatus = String(b.status || '').trim();
  const decision = String(b.decision || '').trim();
  const statusChanged = !!newStatus && newStatus !== lead.status;
  return [{ json: Object.assign(base, {
    status: newStatus || lead.status || 'New',
    notes: (b.notes === undefined || b.notes === null) ? (lead.notes || '') : String(b.notes),
    log_feedback: !!decision || statusChanged,
    feedback_decision: decision || (statusChanged ? 'status_' + newStatus : ''),
  }) }];
}
if (action === 'outreach_action') {
  const op = String(b.op || '');
  if (!['approve', 'edit', 'reject', 'regenerate'].includes(op)) return fail(400, 'op must be approve, edit, reject or regenerate');
  const msg = (b.message === undefined || b.message === null || b.message === '') ? String(lead.outreach_message || '') : String(b.message);
  if (op === 'edit' && !String(b.message || '').trim()) return fail(400, 'message is required for edit');
  const map = { approve: ['Approved', 'Approved'], edit: ['Draft', 'Edited'], reject: ['Rejected', 'Rejected'], regenerate: ['Draft', 'Pending review'] };
  return [{ json: Object.assign(base, {
    op: op,
    message: msg,
    outreach_status: map[op][0],
    human_review_status: map[op][1],
    tone: String(b.tone || ''),
    instructions: String(b.instructions || ''),
    channel: String(b.channel || ''),
    feedback_decision: 'outreach_' + op,
  }) }];
}
if (action === 'outreach_generate') {
  return [{ json: Object.assign(base, { tone: String(b.tone || ''), instructions: String(b.instructions || ''), channel: String(b.channel || '') }) }];
}
if (action === 'service_save') {
  if (!String(b.service_name || '').trim()) return fail(400, 'service_name is required');
  return [{ json: Object.assign(base, {
    row_id: b.id ? String(b.id) : '0',
    service_name: String(b.service_name).trim(),
    description: String(b.description || ''),
    keywords: String(b.keywords || ''),
    capabilities: String(b.capabilities || ''),
    examples: String(b.examples || ''),
    portfolio: String(b.portfolio || ''),
    enabled: !(b.enabled === false || b.enabled === 'false'),
  }) }];
}
if (action === 'service_delete') {
  if (!b.id) return fail(400, 'id is required');
  return [{ json: Object.assign(base, { row_id: String(b.id) }) }];
}
if (action === 'connector_save') {
  if (!String(b.source_name || '').trim()) return fail(400, 'source_name is required');
  return [{ json: Object.assign(base, {
    row_id: b.id ? String(b.id) : '0',
    source_name: String(b.source_name).trim(),
    connector_type: String(b.connector_type || 'brave_web_search'),
    site_filter: String(b.site_filter || ''),
    enabled: !(b.enabled === false || b.enabled === 'false'),
    notes: String(b.notes || ''),
  }) }];
}
if (action === 'settings_save') {
  const s = b.settings && typeof b.settings === 'object' ? b.settings : {};
  const keys = Object.keys(s);
  if (!keys.length) return fail(400, 'settings object is required');
  return [{ json: Object.assign(base, { settings_list: keys.map(k => ({ setting_key: k, setting_value: String(s[k]) })) }) }];
}
return fail(400, 'Unknown action: ' + action);

const lead = $('Research Manual Lead').first().json;
let draft = null;
try { draft = $('Draft Manual Outreach').first().json; } catch (e) { draft = null; }
return [{ json: { lead: lead, outreach: draft } }];

const v = $input.first().json;
return v.leads.map(l => ({ json: {
  candidate_text: String(l.original_post || l.requirement || ''),
  candidate_url: (l.source_url && l.source_url !== 'Not available') ? String(l.source_url) : '',
  candidate_title: '',
  source: String(l.source || 'Manual'),
  post_date: (l.post_date && l.post_date !== 'Not available') ? String(l.post_date) : '',
  instruction_context: v.instruction_context,
  freshness_days: 30,
  origin: 'rescan',
  run_id: String(l.run_id || 'RESCAN'),
  existing_lead_id: String(l.lead_id),
} }));
